package com.mohymods.kingdomsmp.profession;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.mixin.*;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import java.util.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.item.alchemy.*;
import net.minecraft.world.level.block.entity.BrewingStandBlockEntity;
/** Evidence failures never propagate through vanilla inventory transfers or brewing ticks. */
public final class BrewingEvidence {
 public static final String DATA="kingdom_smp_brew_job_v1";
 private BrewingEvidence(){}
 public record Transfer(ServerPlayer player,AbstractContainerMenu menu,BrewingStandBlockEntity stand,Map<String,Integer> sources){}
 public record Tick(BrewingStandBlockEntity stand,CompoundTag job,List<ItemStack> before,int time,int fuel){}
 private static NativeBrewingAccess access(BrewingStandBlockEntity stand){return (NativeBrewingAccess)stand;}
 public static String potion(ItemStack item){return item.getOrDefault(DataComponents.POTION_CONTENTS,PotionContents.EMPTY).potion().flatMap(h->h.unwrapKey()).map(k->k.location().toString()).orElse("");}
 private static boolean plainPotion(ItemStack item){if(!(item.is(Items.POTION)||item.is(Items.SPLASH_POTION))||item.getCount()!=1)return false;var data=item.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();if(!data.isEmpty()){var marker=data.getCompound(EnchantedToolService.KEY);if(!data.getAllKeys().equals(Set.of(EnchantedToolService.KEY))||!marker.getAllKeys().equals(Set.of("store","id"))||!marker.hasUUID("store")||!marker.hasUUID("id"))return false;}var clean=item.copy();clean.remove(DataComponents.CUSTOM_DATA);var holder=item.getOrDefault(DataComponents.POTION_CONTENTS,PotionContents.EMPTY).potion().orElse(null);if(holder==null)return false;var plain=new ItemStack(item.getItem());plain.set(DataComponents.POTION_CONTENTS,new PotionContents(holder));return ItemStack.isSameItemSameComponents(clean,plain);}
 private static boolean permitted(ServerPlayer p,BrewingStandBlockEntity stand){return TreeQuestService.real(p)&&stand.getLevel()==p.serverLevel()&&!stand.isRemoved()&&p.serverLevel().hasChunkAt(stand.getBlockPos())&&p.serverLevel().getBlockEntity(stand.getBlockPos())==stand&&p.serverLevel().getWorldBorder().isWithinBounds(stand.getBlockPos())&&p.distanceToSqr(stand.getBlockPos().getX()+.5,stand.getBlockPos().getY()+.5,stand.getBlockPos().getZ()+.5)<=64&&PlacementProtection.check(p.serverLevel(),p,stand.getBlockPos(),stand.getBlockPos())==null;}
 private static int held(ServerPlayer p,ItemStack reagent){int total=0;for(int i=0;i<36;i++){var stack=p.getInventory().getItem(i);if(ItemStack.isSameItemSameComponents(stack,reagent))total+=stack.getCount();}var cursor=p.containerMenu.getCarried();if(ItemStack.isSameItemSameComponents(cursor,reagent))total+=cursor.getCount();return total;}
 public static Transfer transferBefore(Player actor,AbstractContainerMenu menu){if(!(actor instanceof ServerPlayer p)||!(menu instanceof BrewingStandMenu)||p.containerMenu!=menu||!(menu.getSlot(3).container instanceof BrewingStandBlockEntity stand))return null;try{if(!permitted(p,stand)||access(stand).kingdom$brewTime()!=0||!stand.getItem(3).isEmpty())return null;Map<String,Integer> sources=new HashMap<>();for(var item:List.of(Items.NETHER_WART,Items.GLISTERING_MELON_SLICE,Items.SUGAR,Items.BLAZE_POWDER,Items.MAGMA_CREAM,Items.REDSTONE,Items.GLOWSTONE_DUST,Items.PUFFERFISH,Items.GOLDEN_CARROT,Items.GUNPOWDER))sources.put(BuiltInRegistries.ITEM.getKey(item).toString(),held(p,new ItemStack(item)));return new Transfer(p,menu,stand,Map.copyOf(sources));}catch(RuntimeException failure){TreeLifecycle.failure(p.server,failure);return null;}}
 public static void inputChanged(BrewingStandBlockEntity stand,int slot,ItemStack before){try{if(slot<0||slot>3||ItemStack.matches(before,stand.getItem(slot)))return;var holder=(BrewJobHolder)stand;var job=holder.kingdom$brewJob();if(!job.isEmpty()&&job.getInt("stage")<2)holder.kingdom$brewJob(new CompoundTag());}catch(RuntimeException failure){if(stand.getLevel() instanceof ServerLevel level)TreeLifecycle.failure(level.getServer(),failure);}}
 public static void transferAfter(Transfer t){if(t==null)return;var p=t.player();try{var stand=t.stand();if(p.containerMenu!=t.menu()||!permitted(p,stand)||access(stand).kingdom$brewTime()!=0)return;var ingredient=stand.getItem(3);if(ingredient.isEmpty()||!ItemStack.isSameItemSameComponents(ingredient,new ItemStack(ingredient.getItem())))return;String reagent=BuiltInRegistries.ITEM.getKey(ingredient.getItem()).toString();int previous=t.sources().getOrDefault(reagent,0);if(previous-held(p,ingredient)!=ingredient.getCount())return;
  String quest=null;for(int i=0;i<3;i++){var input=stand.getItem(i);if(input.isEmpty())continue;if(!input.is(Items.POTION)||!plainPotion(input))return;var output=p.serverLevel().potionBrewing().mix(ingredient,input);var route=BrewQuests.route(potion(input),reagent,potion(output),BuiltInRegistries.ITEM.getKey(output.getItem()).toString()).orElse(null);if(route==null||!plainPotion(output)||!NativeOutputQuests.eligible(p,route.quest(),true)||quest!=null&&!quest.equals(route.quest()))return;quest=route.quest();}if(quest==null)return;
  var job=new CompoundTag();job.putInt("schema",1);job.putString("dimension",p.serverLevel().dimension().location().toString());job.putLong("position",stand.getBlockPos().asLong());job.putUUID("owner",p.getUUID());job.putString("quest",quest);job.putInt("stage",0);var inputs=new ListTag();for(int i=0;i<4;i++)inputs.add(stand.getItem(i).saveOptional(p.registryAccess()));job.put("inputs",inputs);job.put("outputs",new ListTag());((BrewJobHolder)stand).kingdom$brewJob(checked(job));stand.setChanged();
 }catch(RuntimeException failure){TreeLifecycle.failure(p.server,failure);}}
 public static CompoundTag checked(CompoundTag job){if(job.isEmpty())return job;if(!job.getAllKeys().equals(Set.of("schema","dimension","position","owner","quest","stage","inputs","outputs"))||!job.contains("schema",Tag.TAG_INT)||job.getInt("schema")!=1||!job.contains("dimension",Tag.TAG_STRING)||net.minecraft.resources.ResourceLocation.tryParse(job.getString("dimension"))==null||!job.contains("position",Tag.TAG_LONG)||!job.hasUUID("owner")||!BrewQuests.contains(job.getString("quest"))||!job.contains("stage",Tag.TAG_INT)||job.getInt("stage")<0||job.getInt("stage")>2||!job.contains("inputs",Tag.TAG_LIST)||job.getList("inputs",Tag.TAG_COMPOUND).size()!=4||!job.contains("outputs",Tag.TAG_LIST)||job.getList("outputs",Tag.TAG_COMPOUND).size()>3||job.getInt("stage")==2&&job.getList("outputs",Tag.TAG_COMPOUND).isEmpty()||job.getInt("stage")<2&&!job.getList("outputs",Tag.TAG_COMPOUND).isEmpty())throw new IllegalArgumentException("Invalid saved native brew job");var recipe=BrewQuests.fromJob(job);var inputs=job.getList("inputs",Tag.TAG_COMPOUND);int bottles=0;for(int i=0;i<3;i++){var input=inputs.getCompound(i);if(input.isEmpty())continue;var bottleRecipe=BrewQuests.fromInput(job.getString("quest"),input,inputs.getCompound(3).getString("id"));checkPotion(input,"minecraft:"+bottleRecipe.input(),"minecraft:potion");bottles++;}var reagent=inputs.getCompound(3);if(bottles==0||!Set.of("id","count","components").containsAll(reagent.getAllKeys())||!reagent.contains("count",Tag.TAG_INT)||reagent.getInt("count")<1||reagent.getInt("count")>64||!reagent.getString("id").equals("minecraft:"+recipe.reagent())||!reagent.getCompound("components").isEmpty())throw new IllegalArgumentException("Invalid saved native brew inputs");var outputs=job.getList("outputs",Tag.TAG_COMPOUND);if(job.getInt("stage")==2&&outputs.size()!=bottles)throw new IllegalArgumentException("Native output count differs from actual inputs");int out=0;for(int slot=0;slot<3&&job.getInt("stage")==2;slot++)if(!inputs.getCompound(slot).isEmpty()){var bottleRecipe=BrewQuests.fromInput(job.getString("quest"),inputs.getCompound(slot),inputs.getCompound(3).getString("id"));checkPotion(outputs.getCompound(out++),"minecraft:"+bottleRecipe.output(),bottleRecipe.item());}return job;}
 private static void checkPotion(CompoundTag item,String potion,String expectedItem){var components=item.getCompound("components");var contents=components.getCompound("minecraft:potion_contents");if(!item.getAllKeys().equals(Set.of("id","count","components"))||!item.contains("count",Tag.TAG_INT)||item.getInt("count")!=1||!item.getString("id").equals(expectedItem)||!Set.of("minecraft:potion_contents","minecraft:custom_data").containsAll(components.getAllKeys())||!contents.getAllKeys().equals(Set.of("potion"))||!contents.getString("potion").equals(potion))throw new IllegalArgumentException("Unsupported saved native potion");if(components.contains("minecraft:custom_data")){var all=components.getCompound("minecraft:custom_data");var marker=all.getCompound(EnchantedToolService.KEY);if(!all.getAllKeys().equals(Set.of(EnchantedToolService.KEY))||!marker.getAllKeys().equals(Set.of("store","id"))||!marker.hasUUID("store")||!marker.hasUUID("id"))throw new IllegalArgumentException("Unsupported native potion marker");}}

 private static boolean sameSite(BrewingStandBlockEntity stand,CompoundTag job){return stand.getLevel()!=null&&stand.getLevel().dimension().location().toString().equals(job.getString("dimension"))&&stand.getBlockPos().asLong()==job.getLong("position");}
 public static Tick before(BrewingStandBlockEntity stand){if(!(stand.getLevel() instanceof ServerLevel level))return null;try{var raw=((BrewJobHolder)stand).kingdom$brewJob();if(raw.isEmpty()||raw.getInt("stage")==2||raw.getInt("stage")==1&&access(stand).kingdom$brewTime()>1)return null;var job=checked(raw);if(!sameSite(stand,job)){((BrewJobHolder)stand).kingdom$brewJob(new CompoundTag());return null;}var before=new ArrayList<ItemStack>();var input=job.getList("inputs",Tag.TAG_COMPOUND);for(int i=0;i<5;i++){var stack=stand.getItem(i).copy();if(i<4&&!ItemStack.matches(stack,ItemStack.parseOptional(level.registryAccess(),input.getCompound(i)))){((BrewJobHolder)stand).kingdom$brewJob(new CompoundTag());return null;}before.add(stack);}if(job.getInt("stage")==0){var p=level.getServer().getPlayerList().getPlayer(job.getUUID("owner"));if(p==null||!permitted(p,stand)||!NativeOutputQuests.eligible(p,job.getString("quest"),true))return null;}return new Tick(stand,job.copy(),List.copyOf(before),access(stand).kingdom$brewTime(),access(stand).kingdom$fuel());}catch(RuntimeException failure){TreeLifecycle.failure(level.getServer(),failure);return null;}}
 public static void after(Tick tick){if(tick==null)return;var stand=tick.stand();var level=(ServerLevel)stand.getLevel();try{var job=tick.job();var holder=(BrewJobHolder)stand;if(job.getInt("stage")==0&&tick.time()==0&&access(stand).kingdom$brewTime()==400&&(tick.fuel()>0&&access(stand).kingdom$fuel()==tick.fuel()-1||tick.fuel()==0&&access(stand).kingdom$fuel()==19&&tick.before().get(4).is(Items.BLAZE_POWDER)&&stand.getItem(4).getCount()==tick.before().get(4).getCount()-1)){job.putInt("stage",1);holder.kingdom$brewJob(job);stand.setChanged();return;}if(job.getInt("stage")!=1||tick.time()!=1||access(stand).kingdom$brewTime()!=0)return;var reagent=tick.before().get(3);var current=stand.getItem(3);if(current.getCount()!=reagent.getCount()-1||!current.isEmpty()&&!ItemStack.isSameItemSameComponents(current,reagent))return;
  var outputs=new ListTag();for(int i=0;i<3;i++){var old=tick.before().get(i);var result=stand.getItem(i);if(old.isEmpty()){if(!result.isEmpty())return;continue;}var expected=level.potionBrewing().mix(reagent,old);if(!ItemStack.matches(result,expected)||result.is(old.getItem())&&potion(result).equals(potion(old))||!plainPotion(result)||!potion(result).equals("minecraft:"+BrewQuests.fromInput(job.getString("quest"),(CompoundTag)old.save(level.registryAccess()),BuiltInRegistries.ITEM.getKey(reagent.getItem()).toString()).output()))return;}
  for(int i=0;i<3;i++){var result=stand.getItem(i);if(result.isEmpty())continue;var all=result.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();var marker=new CompoundTag();marker.putUUID("store",CommerceService.store(level.getServer()).id());marker.putUUID("id",UUID.randomUUID());all.put(EnchantedToolService.KEY,marker);result.set(DataComponents.CUSTOM_DATA,CustomData.of(all));outputs.add(result.save(level.registryAccess()));}job.put("outputs",outputs);job.putInt("stage",2);holder.kingdom$brewJob(job);stand.setChanged();
 }catch(RuntimeException failure){TreeLifecycle.failure(level.getServer(),failure);}}
 public static void take(Player actor,Slot slot,ItemStack nativeOutput){if(!(actor instanceof ServerPlayer p)||!(slot.container instanceof BrewingStandBlockEntity stand))return;try{var job=checked(((BrewJobHolder)stand).kingdom$brewJob());if(job.isEmpty()||!sameSite(stand,job)||job.getInt("stage")!=2||!job.getUUID("owner").equals(p.getUUID())||!permitted(p,stand)||!NativeOutputQuests.eligible(p,job.getString("quest"),true))return;var identity=(NativeItemIdentityAccessor)(Object)nativeOutput;var outputs=job.getList("outputs",Tag.TAG_COMPOUND);for(var row:outputs){var encoded=(CompoundTag)row;var expected=ItemStack.parse(p.registryAccess(),encoded).orElseThrow();if(identity.kingdom$nativeItem()!=expected.getItem()||!identity.kingdom$nativeComponents().equals(((NativeItemIdentityAccessor)(Object)expected).kingdom$nativeComponents()))continue;var marker=expected.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound(EnchantedToolService.KEY);var store=CommerceService.store(p.server);if(store.matchesNativeOutput(marker.getUUID("id"),p.getUUID(),job.getString("quest"),encoded))return;store.issueNativeOutput(marker.getUUID("id"),p.getUUID(),job.getString("quest"),encoded);return;}
 }catch(java.io.IOException|RuntimeException failure){TreeLifecycle.failure(p.server,new IllegalStateException("Native brew output retained; matching evidence unavailable",failure));}}
}
